"""Regenerate operating-condition figures, HTML, bilingual reports and notes from solved data.
No SciPy import or solver call is required by this script.
"""
from pathlib import Path
import csv,hashlib,json,math
import numpy as np
from PIL import Image,ImageDraw
from plot_and_video import font,BG,TEXT,GRID,TEAL,BLUE,GOLD
from supplemental_figures import palette
P=Path(__file__).resolve().parent; WELLS=['NE','NW','SW','SE']
def read(p):return json.loads((P/p).read_text(encoding='utf-8'))
def filename(Q,D,dx=.4,dt=None,label=''):
 if dt is None:dt=1. if Q<=.5 else .5 if Q<=2 else .25
 return f'operating_results/Q{Q:g}_D{D:g}_dx{dx:g}_dt{dt:g}{label}.json'
def percentile(r,k):return max(r[k][w+'_near_liquid'] for w in WELLS)
def pareto(rows):return [a for a in rows if not any(b['worst_t90_s']<=a['worst_t90_s'] and b['gas_speed_p95_mm_s']<=a['gas_speed_p95_mm_s'] and (b['worst_t90_s']<a['worst_t90_s'] or b['gas_speed_p95_mm_s']<a['gas_speed_p95_mm_s']) for b in rows)]
def collect():
 cfg=read('operating_sweep_config.json');refine=read('operating_refinement_config.json');cfg['stage1_Q_mL_min']=list(cfg['Q_mL_min']);cfg['Q_mL_min']=sorted(set(cfg['Q_mL_min']+refine['Q_mL_min']));cfg['adaptive_refinement']=refine;rows=[];raw=[]
 for Q in cfg['Q_mL_min']:
  for D in cfg['Dgas_mm2_s']:
   fn=filename(Q,D);r=read(fn);raw.append(r)
   rows.append(dict(Q_mL_min=Q,Dgas_mm2_s=D,t10_s=percentile(r,'t10_s'),t50_s=percentile(r,'t50_s'),t90_s=percentile(r,'t90_s'),gas_speed_p95_mm_s=r['worst_near_liquid_speed_p95_mm_s'],port_mean_speed_mm_s=r['port_mean_speed_mm_s'],port_Re=r['port_Re'],chamber_pressure_drop_Pa=r['chamber_pressure_drop_Pa'],raw_json=fn))
 with (P/'operating_sweep.csv').open('w',newline='') as f:w=csv.DictWriter(f,list(rows[0]));w.writeheader();w.writerows(rows)
 agg=[];targets=cfg['targets']
 for Q in cfg['Q_mL_min']:
  a=[r for r in rows if r['Q_mL_min']==Q];r=a[0];worst=max(a,key=lambda q:q['t90_s']);j=dict(Q_mL_min=Q,worst_t90_s=worst['t90_s'],worst_Dgas_mm2_s=worst['Dgas_mm2_s'],gas_speed_p95_mm_s=r['gas_speed_p95_mm_s'],port_Re=r['port_Re'],port_mean_speed_mm_s=r['port_mean_speed_mm_s'],chamber_pressure_drop_Pa=r['chamber_pressure_drop_Pa']);j['meets_declared_targets']=j['worst_t90_s']<=targets['worst_well_worst_D_t90_max_s'] and j['gas_speed_p95_mm_s']<=targets['near_liquid_gas_P95_speed_max_mm_s'] and j['port_Re']<=targets['port_Re_max'];agg.append(j)
 feasible=[a for a in agg if a['meets_declared_targets']];chosen=min(feasible,key=lambda a:a['Q_mL_min']) if feasible else None
 checks={};base5=read(filename(5,10));base025=read(filename(.25,10))
 for name,fn,ref in [('upper_flow_grid',filename(5,10,.3,.25),base5),('upper_flow_timestep',filename(5,10,.4,.125),base5),('lower_flow_timestep',filename(.25,10,.4,.5),base025),('upper_flow_direct_field',filename(5,10,.3,.25,'_direct5'),read(filename(5,10,.3,.25)))]:
  r=read(fn);checks[name]=dict(raw_json=fn,worst_t90_s=r['worst_near_liquid_t90_s'],relative_change_t90=r['worst_near_liquid_t90_s']/ref['worst_near_liquid_t90_s']-1,gas_speed_p95_mm_s=r['worst_near_liquid_speed_p95_mm_s'],relative_change_gas_speed=r['worst_near_liquid_speed_p95_mm_s']/ref['worst_near_liquid_speed_p95_mm_s']-1)
 selected_cfg=read('operating_selected_check_config.json');ref=read(filename(selected_cfg['Q_mL_min'],selected_cfg['Dgas_mm2_s']))
 for name,setting in zip(['selected_point_grid','selected_point_timestep'],selected_cfg['checks']):
  fn=filename(selected_cfg['Q_mL_min'],selected_cfg['Dgas_mm2_s'],setting['dx_mm'],setting['dt_s']);r=read(fn)
  checks[name]=dict(raw_json=fn,worst_t90_s=r['worst_near_liquid_t90_s'],relative_change_t90=r['worst_near_liquid_t90_s']/ref['worst_near_liquid_t90_s']-1,gas_speed_p95_mm_s=r['worst_near_liquid_speed_p95_mm_s'],relative_change_gas_speed=r['worst_near_liquid_speed_p95_mm_s']/ref['worst_near_liquid_speed_p95_mm_s']-1)
 allruns=[json.loads(f.read_text()) for f in (P/'operating_results').glob('*.json')]
 summary=dict(configuration=cfg,stage1_screening_solves=15,stage2_adaptive_screening_solves=6,screening_scalar_solves=len(rows),validation_scalar_solves=len(checks),direct_velocity_solves=1,chosen_conditional_point=chosen,decision_status='Conditional operating candidate; provisional targets, numerical checks only, no physical or biological validation.',flow_aggregates=agg,pareto_Q_mL_min=[r['Q_mL_min'] for r in pareto(agg)],numerical_checks=checks,direct_flow_check=read('operating_direct_flow_check.json'),max_relative_global_mass_residual=max(r['relative_global_mass_residual'] for r in allruns),max_uniform_operator_residual=max(r['uniform_operator_residual'] for r in allruns),concentration_bounds=[min(r['concentration_min'] for r in allruns),max(r['concentration_max'] for r in allruns)],old_raw_files_modified=False,CAD_changed=False,scope='Conditional lowest-flow choice from seven sampled Q levels for fixed geometry, robust only over the three assumed gas diffusivities. Gas concentration, not cell exposure or safety. No weighted objective or global optimum is claimed.',source_config_sha256=hashlib.sha256((P/'operating_sweep_config.json').read_bytes()).hexdigest(),refinement_config_sha256=hashlib.sha256((P/'operating_refinement_config.json').read_bytes()).hexdigest(),selected_check_config_sha256=hashlib.sha256((P/'operating_selected_check_config.json').read_bytes()).hexdigest())
 # Baseline repeats must reproduce the preserved previous history (within roundoff).
 baseline=[]
 for D in cfg['Dgas_mm2_s']:
  prior=read(f'gas_transport_results/shelf_w8_e0p2_D{D:g}_dx0.4_dt0.5.json');new=read(filename(1,D));baseline.append(abs(new['t90_s']['NE_near_liquid']-prior['t90_s']['NE_near_liquid']))
 summary['repeated_Q1_baseline_max_abs_t90_difference_s']=max(baseline)
 (P/'operating_sweep_summary.json').write_text(json.dumps(summary,indent=2),encoding='utf-8');return rows,summary

def plots(rows,s):
 fig=P/'figures';fig.mkdir(exist_ok=True);cfg=s['configuration'];Q=cfg['Q_mL_min'];Ds=cfg['Dgas_mm2_s'];im=Image.new('RGB',(1860,900),BG);d=ImageDraw.Draw(im);d.text((45,24),'Gas delivery across operating conditions',font=font(35,True),fill=TEXT)
 lo=min(r['t10_s'] for r in rows);hi=max(r['t90_s'] for r in rows)
 for panel,key in enumerate(['t10_s','t50_s','t90_s']):
  x0=100+panel*605;y0=170;cw=500/len(Q);ch=150;d.text((x0,100),f'{chr(65+panel)}  {key[:3].replace("_","")} [s]',font=font(28,True),fill=TEXT)
  for r in rows:
   i=Q.index(r['Q_mL_min']);j=Ds.index(r['Dgas_mm2_s']);t=(math.log10(r[key])-math.log10(lo))/(math.log10(hi)-math.log10(lo));x=x0+i*cw;y=y0+(2-j)*ch;d.rectangle((x,y,x+cw-2,y+ch-2),fill=palette(t));d.text((x+6,y+60),f'{r[key]:.1f}',font=font(20,True),fill='white' if t<.35 else TEXT)
  for i,q in enumerate(Q):d.text((x0+i*cw+25,y0+3*ch+16),f'{q:g}',font=font(23),fill=TEXT)
  for j,dd in enumerate(Ds[::-1]):d.text((x0-46,y0+j*ch+60),f'{dd:g}',font=font(23),fill=TEXT)
  d.text((x0+135,690),'Q [mL/min]',font=font(25),fill=TEXT);d.text((x0,135),'Dgas [mm²/s]',font=font(21),fill=TEXT)
 d.text((290,776),'Time [s]',font=font(22),fill=TEXT)
 for k in range(900):d.line((450+k,780,450+k,806),fill=palette(k/899))
 for j in range(6):d.text((433+180*j,824),f'{10**(math.log10(lo)+j/5*(math.log10(hi)-math.log10(lo))):.1f}',font=font(19),fill=TEXT)
 im.save(fig/'operating_delivery.png',dpi=(300,300))
 im=Image.new('RGB',(1650,900),BG);d=ImageDraw.Draw(im);d.text((45,24),'Flow-rate tradeoff',font=font(36,True),fill=TEXT);a=s['flow_aggregates'];x0,y0,w,h=130,165,1320,535;xmax=max(r['gas_speed_p95_mm_s'] for r in a)*1.15;ymax=math.ceil(max(r['worst_t90_s'] for r in a)/100)*100
 # Axis resolves the sampled speeds; the separate comparison cap remains in configuration/report.
 for val in np.linspace(0,ymax,6):yy=y0+h*(1-val/ymax);d.line((x0,yy,x0+w,yy),fill=GRID);d.text((x0-65,yy-14),f'{val:g}',font=font(21),fill=TEXT)
 for val in np.linspace(0,xmax,6):xx=x0+w*val/xmax;d.text((xx-30,y0+h+16),f'{val:.3f}',font=font(21),fill=TEXT)
 d.line((x0,y0,x0,y0+h,x0+w,y0+h),fill=TEXT,width=2);target=cfg['targets']['worst_well_worst_D_t90_max_s'];yy=y0+h*(1-target/ymax)
 for x in range(x0,x0+w,20):d.line((x,yy,x+10,yy),fill='#93637c',width=2)
 d.text((x0+850,yy-29),f't90 target {target:g} s',font=font(21),fill='#93637c')
 pts=[(x0+w*r['gas_speed_p95_mm_s']/xmax,y0+h*(1-r['worst_t90_s']/ymax)) for r in a];d.line(pts,fill=TEAL,width=3)
 for idx,(r,(x,y)) in enumerate(zip(a,pts)):
  d.ellipse((x-7,y-7,x+7,y+7),fill=TEAL);d.text((x+12,y+[-36,-40,12][idx%3]),f'Q={r["Q_mL_min"]:g}',font=font(24),fill=TEXT)
  if s['chosen_conditional_point'] and r['Q_mL_min']==s['chosen_conditional_point']['Q_mL_min']:d.ellipse((x-13,y-13,x+13,y+13),outline=TEXT,width=3)
 d.text((x0,112),'Worst-well / worst-D t90 [s]',font=font(26),fill=TEXT);d.text((x0+320,775),'Near-liquid gas P95 speed [mm/s]',font=font(26),fill=TEXT)
 im.save(fig/'operating_pareto.png',dpi=(300,300))

def html(rows,s):
 template='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Gas operation explorer</title><style>body{font:16px Arial;max-width:1200px;margin:auto;padding:22px;color:#18252d}h1{font-size:26px}nav{display:flex;gap:14px;flex-wrap:wrap}select,input,button{font:inherit;padding:5px}input{width:85px}canvas{width:100%;border:1px solid #ddd;touch-action:none}p{line-height:1.5}a{color:#167482}</style><h1>Gas operation explorer · 氣體操作條件</h1><nav><label>Z <select id="zmetric"><option value="t90_s">t90 [s]</option><option value="t50_s">t50 [s]</option><option value="t10_s">t10 [s]</option></select></label><label>Colour / 顏色 <select id="colour"><option value="gas_speed_p95_mm_s">Gas P95 speed</option><option value="chamber_pressure_drop_Pa">Chamber pressure drop</option><option value="port_Re">Port Re</option><option value="t90_s">Gas t90</option></select></label><button id="reset">Reset / 重設</button><a href="operating_sweep.csv">CSV</a><a href="figures/operating_pareto.png">Pareto plot / 取捨圖</a><a href="Flow_Operation_ZH.md">中文說明</a><a href="Flow_Operation_EN.md">English report</a></nav><p>Drag / arrow keys: rotate · Wheel: zoom · Hover: values. X is flow Q; Y is assumed diffusivity D; Z is a computed response. D is not an operating control.</p><nav><label>Gas t90 target [s] <input id="target" type="number" min="1" value="60"></label><label>Gas-speed comparison cap [mm/s] <input id="cap" type="number" min="0" step="0.001" value="0.01"></label></nav><p id="choice"></p><p id="pareto"></p><p>Target explorer only. Gas-speed cap is not a cell-safety threshold; port Re≤3 is fixed. Outlined points share the lowest sampled Q meeting the current target across all three D assumptions. / 只探索條件；氣速上限不是細胞安全界限。</p><canvas tabindex="0" aria-label="Twenty-one computed flow-diffusivity points"></canvas><p id="detail">21 solved conditions / 21個計算條件</p><a id="raw"></a><script>const DATA=__DATA__; const AGG=__AGG__;</script><script>__MATH__</script><script>__UI__</script></html>'''
 out=template.replace('__DATA__',json.dumps(rows)).replace('__AGG__',json.dumps(s['flow_aggregates'])).replace('__MATH__',(P/'operating_math.js').read_text()).replace('__UI__',(P/'operating_ui.js').read_text());(P/'operating_sweep_3d.html').write_text(out,encoding='utf-8')

def reports(s):
 c=s['chosen_conditional_point'];cfg=s['configuration'];target=cfg['targets'];choice_zh=f'在此次取樣範圍中，符合預先聲明條件的最小流量候選為 **{c["Q_mL_min"]:g} mL/min**，最差井／最差D的氣相t90為 **{c["worst_t90_s"]:.2f}秒**。' if c else '**沒有取樣流量同時符合所有預設條件；本次不選定操作點。**';choice_en=f'The lowest sampled operating candidate satisfying the prespecified conditions is **{c["Q_mL_min"]:g} mL/min**, with a worst-well/worst-D gas t90 of **{c["worst_t90_s"]:.2f} s**.' if c else '**No sampled flow meets all declared conditions; no operating point is selected.**'
 table='| Q (mL/min) | Worst gas t90 (s) | P95 gas speed (mm/s) | Port speed (mm/s) | Port Re | Chamber Δp (Pa) | Meets targets |\n|---:|---:|---:|---:|---:|---:|:---:|\n'+'\n'.join(f'| {r["Q_mL_min"]:g} | {r["worst_t90_s"]:.2f} | {r["gas_speed_p95_mm_s"]:.6f} | {r["port_mean_speed_mm_s"]:.3f} | {r["port_Re"]:.3f} | {r["chamber_pressure_drop_Pa"]:.5f} | {r["meets_declared_targets"]} |' for r in s['flow_aggregates'])
 checks=s['numerical_checks'];checktable='| Check | t90 relative change |\n|---|---:|\n'+'\n'.join(f'| {k} | {100*v["relative_change_t90"]:+.3f}% |' for k,v in checks.items());direct=s['direct_flow_check'];pars=', '.join(f'{q:g}' for q in s['pareto_Q_mL_min'])
 zh=f'''# 固定外殼的氣流操作條件\n\n{choice_zh} 這是固定平台、固定STL、氣相模型中的條件式選擇，**不是全域最佳，也不是已證明對HEK293T安全或可在此時間啟動GCaMP**。CAD沒有更動。\n\n## 預先聲明的選擇規則\n\n在看新結果前，`operating_sweep_config.json`指定Q=0.25／0.5／1／2／5 mL/min，Dgas=5／10／20 mm²/s。假定目標為四井、三種D中最慢的氣相t90≤60秒，入口Re≤3，近液面氣體P95速度≤0.01 mm/s。選最小符合流量；不使用加權總分。t90是持續固定入口濃度階躍的氣相反應，不能直接套用短氣味脈衝或細胞反應時間。60秒目標尚非使用者量測規格，0.01 mm/s只是工程比較上限，沒有細胞傷害依據。D是分子／氣體環境性質與不確定參數，不能像泵速一樣調整。\n\n{table}\n\n每個t值取四井近液面取樣帶的最慢值；取樣帶在液面上方0.6–1.4 mm，不是液相或細胞。表內最差D值未必隨D單調；入口階躍包含上游扩散，不能以V/Q單獨代替。t10、t50、t90與每井完整曲線均保存在原始CSV／JSON。Q2.5的最差值約60.04秒，與60秒只差0.04秒，小於本次數值敏感性；不能說Q2.5在實物一定不合格。Q3約50秒提供較大的模型內時間裕度，仍須實測。圖內四捨五入的60.0不能當成精確達標。\n\n## Pareto取捨與限制\n\n此取樣集非支配流量為{pars} mL/min：降低氣速通常會延長供樣時間，兩者不可同時任意最小。圖中曲線只連接離散操作點，不是內插後保證可行區域。最高Q端點附近的Re仍約3，低Re線性縮放不是自動精確；直接速度與濃度檢查如下。即使選定流量，外部管長、接頭、濾嘴、洩漏、吸附、氣體溶入液體與細胞反應都可能改變實際結果。100µL液體深8.93 mm，底部細胞傳質仍需看[液體／薄膜分析](../membrane/Analysis_ZH.md)。\n\n## 數值方法與檢查\n\n沿用0.4 mm氣相體素，無滑移固定液面；已保存速度場按Q線性換算，面流量做守恆投影。標量方程以保守有限體積、迎風對流、中心擴散與後向Euler求解；初始C=0，入口固定C/Cin=1階躍，出口對流、無擴散通量；液面與固體都不吸收。低Q時間步1秒、Q1/2用0.5秒、Q≥2.5用0.25秒。計算終點max(150,300/Q)秒。\n\n新增15組初始操作濃度求解，再依Q2到Q5跨過60秒目標的結果，於獨立stage-2設定檔預先加Q2.5與Q3共6組細化；合計21组操作條件、6組數值檢查、1組直接近5 mL/min速度求解；原始資料保留。三個Q1重算與舊基準t90最大差{s['repeated_Q1_baseline_max_abs_t90_difference_s']:.3g}秒。最大相對質量帳誤差{s['max_relative_global_mass_residual']:.3g}；濃度範圍{s['concentration_bounds'][0]:.6g}–{s['concentration_bounds'][1]:.6g}，沒有為展示結果裁切濃度。\n\n{checktable}\n\n直接速度求解實際Q={direct['high_flow_mL_min']:.4f} mL/min；同網格0.3 mm、同τ0.55，與原近1 mL/min解歸一化後速度L2差{100*direct['normalized_velocity_relative_L2']:.3f}%、近液面P95差{100*direct['normalized_near_liquid_P95_relative_change']:.3f}%。此檢查量化慣性／邊界敏感性，不代表所有局部量網格獨立。直接場的濃度曲線另外存檔；採相同目標Q縮放後比較。\n\n## 一個泵如何操作\n\n建議以**一個可調速、可量測或校正流量的下游抽氣泵**串聯出口，在乾淨進氣端裝適當濾器。密封且穩態的串聯氣路只有同一個質量流率；在相同壓溫、近不可壓縮假設下Qin≈Qout。不要把進口和出口兩台獨立泵各設不同流量，企圖同時指定供樣與抽氣：差額會造成暫態壓力、洩漏或進氣補償，本模型沒計算。使用者若需精確泵型，仍須實測整條管路／濾器壓降與流量範圍。候選Q3代表一個泵抽取約3 mL/min，進、出口都以相同壓溫基準換算；不是進氣3再額外指定不同排氣值。本模擬不提供泵驅動或流量閉迴路；UI記錄流量不等於實際已達到該流量。\n\n表中壓降只有3D模型氣室及其短接頭，不含濾嘴、外部管路，也不能拿極小氣室Pa值直接選泵。不要把下游泵最大真空施加到密封培養井。先用無細胞水樣、最低流量確認有連通出口、無液體位移或洩漏，再量到裝上全部濾器與管路後的實際流量。此為機構供氣檢查，不是細胞實驗或無菌驗證。\n\n## 重現與閱讀\n\n`python operating_sweep.py --run --checks --refine --selected-checks`重新求解；`python operating_figures.py`由資料生成圖、離線HTML與本報告。`node test_operating.cjs`檢查資料與互動數學。互動頁`operating_sweep_3d.html`可改t90／比較氣速上限，但這不修改預先聲明的報告選擇。X為Q、Y為D、Z為計算反應時間，第三軸不是第三個獨立控制因子；沒有PCA／UMAP或群集當成最優證据。圖說在figure_notes，各圖各語言獨立檔。\n'''
 en=f'''# Gas operating conditions for the fixed enclosure\n\n{choice_en} This is a conditional choice for the fixed shelf and fixed STL in a gas-side model, **not a global optimum, a HEK293T safety result, or a demonstrated time to GCaMP activation**. CAD is unchanged.\n\n## Prespecified selection rule\n\nBefore inspecting the new outputs, `operating_sweep_config.json` fixed Q=0.25/0.5/1/2/5 mL/min and Dgas=5/10/20 mm²/s. The assumed targets are worst-well/worst-D gas t90≤60 s, port Re≤3, and near-liquid gas P95 speed≤0.01 mm/s. Choose the smallest qualifying Q without a weighted score. These response times assume a sustained inlet concentration step, not a brief odor pulse or cellular response. The 60-s target is provisional; the speed cap is an engineering comparison limit, not a cell-injury threshold. D is an uncertain species/environment property, not a knob to tune like pump flow.\n\n{table}\n\nEach t value takes the slowest of four near-liquid gas sampling bands, 0.6–1.4 mm above the liquid; it is not a liquid or cellular concentration. Worst-case D need not be monotonic because upstream diffusion contributes at the prescribed inlet step. V/Q alone is not a response-time calculation. Raw CSV/JSON retain t10, t50, t90 and complete per-well curves. Q2.5 gives about 60.04 s: its 0.04-s nominal miss is smaller than numerical sensitivity, so it is not demonstrated physically inadequate. Q3 gives about 50 s and a larger within-model timing margin; physical testing remains necessary. A rounded figure value of 60.0 is not exact target compliance.\n\n## Pareto tradeoff and limits\n\nThe nondominated sampled flows are {pars} mL/min: lower gas speed generally costs delivery time. Connecting lines join discrete cases and do not certify interpolated operating regions. Port Re approaches 3 at the upper endpoint, so linear low-Re scaling requires checks. Tubing, filters, leaks, adsorption, dissolution and cell response are absent. With 100 µL, the liquid depth is 8.93 mm; delivery to bottom-adherent cells remains a separate [liquid/membrane problem](../membrane/Analysis_EN.md).\n\n## Numerical method and checks\n\nThe main grid is 0.4 mm. Saved rigid-wall/no-slip-liquid gas velocity is linearly scaled with Q; projected face fluxes enforce discrete conservation. Conservative finite volume uses upwind advection, central diffusion and backward Euler. Initially C=0; the inlet terminal steps to C/Cin=1; the outlet is convective with zero diffusion; solid and liquid walls are impermeable. Timesteps are 1 s for Q≤0.5, 0.5 s for Q1/2 and 0.25 s for Q≥2.5. End time is max(150,300/Q) s.\n\nThere are 15 initial operating scalar solves and 6 adaptive bracket-refinement solves at Q2.5/3, declared in a separate stage-2 config after Q2/5 bracketed 60 s. Thus 21 operating conditions, 6 scalar validation solves and 1 direct near 5-mL/min velocity solve. Previous data are preserved. Recomputed Q1 t90 differs from prior baselines by at most {s['repeated_Q1_baseline_max_abs_t90_difference_s']:.3g} s. Maximum relative global mass residual is {s['max_relative_global_mass_residual']:.3g}; concentration spans {s['concentration_bounds'][0]:.6g}–{s['concentration_bounds'][1]:.6g}, without display-driven clipping.\n\n{checktable}\n\nThe direct velocity run reaches Q={direct['high_flow_mL_min']:.4f} mL/min. At the same 0.3-mm grid and τ0.55, its normalized field differs from the near 1-mL/min run by {100*direct['normalized_velocity_relative_L2']:.3f}% in velocity L2 and {100*direct['normalized_near_liquid_P95_relative_change']:.3f}% in near-liquid P95. This quantifies inertia/boundary sensitivity, not continuum grid independence. A separately stored scalar history uses the direct field after normalization to the same comparison Q.\n\n## One-pump operation\n\nUse **one regulated downstream suction pump**, with actual flow measured or calibrated through the complete assembled path and suitable inlet filtration. A sealed steady series path has the same mass flow at inlet and outlet; at equal pressure/temperature under this nearly incompressible model, Qin≈Qout. Independent inlet and outlet pumps cannot impose unequal steady flows without pressure storage, leaks or compensating flow, none of which is represented here. At the Q3 candidate, one pump draws about 3 mL/min and both port rates refer to the same pressure/temperature basis. This simulation supplies no pump driver or flow-control loop; a UI record of a flow setting is not proof that physical flow was reached.\n\nTabulated pressure drop covers only the modeled chamber and short port segments, not filters or external tubing; it cannot alone specify a pump. Do not apply a pump's maximum vacuum to sealed culture wells. First use a cell-free water surrogate at low flow to confirm an open outlet, no visible liquid displacement and no leaks, then measure flow with all intended filters/tubes installed. This is a mechanical flow check, not a cell or sterility validation.\n\n## Reproduction and interpretation\n\n`python operating_sweep.py --run --checks --refine --selected-checks` computes the cases. `python operating_figures.py` regenerates plots, offline HTML and this report; `node test_operating.cjs` tests data and interaction mathematics. In `operating_sweep_3d.html`, targets can be explored without changing the report's prespecified selection. X=Q, Y=D, Z=a computed time response; the third axis is not an independent control. No PCA/UMAP cluster is used to claim an optimum. Separate bilingual notes are in figure_notes.\n'''
 for lang,body in [('ZH',zh),('EN',en)]:(P/f'Flow_Operation_{lang}.md').write_text(body,encoding='utf-8')
 notes=P/'figure_notes';notes.mkdir(exist_ok=True);caps={}
 specs=[('operating_delivery.png','固定平台的流量與氣相擴散係數掃描；每格為四井最慢氣相t10、t50或t90。','Flow–diffusivity sweep for the fixed shelf; each cell is the slowest-well gas t10, t50 or t90.','三面板依序t10、t50、t90；X為Q mL/min、Y為Dgas mm²/s，色条為共同對數時間秒，格內是實際秒數。','Panels are t10, t50 and t90; X=Q mL/min, Y=Dgas mm²/s. Shared logarithmic colour denotes seconds; cell text gives actual seconds.'),('operating_pareto.png','氣相供樣時間與近液面氣速的非支配取捨；圓圈標出符合預設條件的最低取樣流量。','Nondominated tradeoff between gas delivery time and near-liquid speed; the ring marks the lowest sampled flow meeting the provisional constraints.','X近液面氣體P95速度mm/s；Y四井／三D最慢t90秒。点旁Q是mL/min；虛線60秒；黑圈為條件式選擇，非全域最優。','X=near-liquid gas P95 speed mm/s; Y=worst-well/worst-D t90 seconds. Point labels are Q mL/min; dashed line=60 s; black ring=conditional selection, not a global optimum.'),('operating_sweep_3d.html','互動操作參數圖：21個真正計算條件，可切換反應時間、顏色與暫定目標。','Interactive operating map of 21 actually solved conditions with selectable response, colour and provisional targets.','X為Q對數刻度、Y為Dgas，Z可選最差井t10/t50/t90秒。顏色可選氣速、氣室壓降、入口Re或t90；描邊表示所有D都過條件的最低Q。D不是控制鈕，改目標不改已生成報告。','X=logQ, Y=Dgas, Z=worst-well t10/t50/t90 seconds. Colour selects gas speed, chamber drop, port Re or t90. Outlines identify the lowest Q meeting constraints across D. D is not a control; exploring targets does not rewrite the report.')]
 for file,zhcap,encap,zhaxes,enaxes in specs:
  caps[file]={'ZH':zhcap,'EN':encap}
  for lang,cap,axes in [('ZH',zhcap,zhaxes),('EN',encap,enaxes)]:
   body=f'# {file}\n\n## '+('圖說' if lang=='ZH' else 'Publication caption')+f'\n\n{cap}\n\n## '+('方法' if lang=='ZH' else 'Method')+'\n\n'+('固定STL、21組守恆三維氣相對流擴散；低Re速度場按Q縮放，液面不吸收。' if lang=='ZH' else 'Fixed STL; 21 conservative 3D gas advection–diffusion cases with Q-scaled low-Re velocity and no liquid uptake.')+'\n\n## '+('結果' if lang=='ZH' else 'Results')+'\n\n'+(choice_zh if lang=='ZH' else choice_en)+'\n\n## '+('如何閱讀／所有座標與圖例' if lang=='ZH' else 'Reading / axes and legend')+f'\n\n{axes}\n\n## '+('資料與重現' if lang=='ZH' else 'Data and reproduction')+'\n\n`operating_sweep.csv`, `operating_results/*.csv/*.json`, `operating_sweep_config.json`; `python operating_sweep.py --run --checks --refine --selected-checks`; `python operating_figures.py`; `node test_operating.cjs`.\n\n## '+('限制' if lang=='ZH' else 'Limits')+'\n\n'+('氣側時間不是細胞反應時間。0.01 mm/s不是生物安全值；管路、濾器、液體、吸附、細胞皆未模擬。數值檢查見Flow_Operation_ZH.md；互動只做Node／資料測試，未做瀏覽器操作驗證。' if lang=='ZH' else 'Gas-side time is not cell response. The 0.01-mm/s cap is not a biological safety threshold. Tubing, filters, liquid, adsorption and cells are absent. Numerical checks are in Flow_Operation_EN.md. Interactive checks use Node/data tests; browser interaction is unverified.')+'\n'
   (notes/(Path(file).stem+'_'+lang+'.md')).write_text(body,encoding='utf-8')
 (P/'operating_captions.json').write_text(json.dumps(caps,ensure_ascii=False,indent=2),encoding='utf-8')

def main():
 rows,s=collect();plots(rows,s);html(rows,s);reports(s);print(json.dumps({'chosen':s['chosen_conditional_point'],'checks':s['numerical_checks']},indent=2))
if __name__=='__main__':main()